  }

  ns.tprint(`Hacking ${best.name}...`);
  while (true) {
    await ns.hack(best.name);
    const money = ns.getServerMoneyAvailable(best.name);
    if (money > 0) {
      ns.tprint(`Gained money! ${money}`);
    }
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const servers = [];
  const visited = new Set();
  const queue = ['home'];

  while (queue.length > 0) {
    const srv = queue.shift();
    if (visited.has(srv)) continue;
    visited.add(srv);

    const maxMoney = ns.getServerMaxMoney(srv);
    const minSec = ns.getServerMinSecurityLevel(srv);
    const growth = ns.getServerGrowth(srv);

    if (maxMoney > 0 && growth > 0) {
      servers.push({name: srv, growth, maxMoney});
    }

    const children = ns.scan(srv);
    for (const child of children) {
      if (!visited.has(child)) queue.push(child);
    }
  }

  servers.sort((a, b) => b.growth - a.growth);
  const target = servers[0]?.name || 'n00dles';

  if (!ns.hasRootAccess(target)) ns.nuke(target);

  while (true) {
    await ns.hack(target);
  }
}
